import { forwardRef, type SelectHTMLAttributes } from "react";

export const NativeSelect = forwardRef<HTMLSelectElement, SelectHTMLAttributes<HTMLSelectElement>>(({ className = "", ...props }, ref) => <select ref={ref} className={`co-h-10 co-w-full co-rounded-md co-border co-border-black/20 co-bg-white co-px-3 co-text-sm co-outline-none focus-visible:co-ring-2 disabled:co-opacity-50 ${className}`.trim()} {...props} />);
NativeSelect.displayName = "NativeSelect";
